package com.koratalyoum.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 int bg=0xff071316,card=0xff132329,green=0xff19d990,white=0xfff3f7f6,muted=0xffa7b8b8; LinearLayout root,body; String tab="اليوم",key="";int offset=0;
 int[] ids={307,39,140,135,78,61,2,3,848,17,4};
 public void onCreate(Bundle b){super.onCreate(b);key=getPreferences(0).getString("key","");show();}
 TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(14,13,14,13);t.setGravity(Gravity.RIGHT);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;}
 void add(LinearLayout l,View v){l.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 void action(LinearLayout l,String s,Runnable r){TextView t=label(s,16,green);add(l,t);t.setOnClickListener(v->r.run());}
 void show(){root=column();root.setBackgroundColor(bg);setContentView(root);add(root,label("⚽ كورة اليوم",29,green));add(root,label("نتائج كرة القدم • بتوقيت السعودية • بدون إعلانات",13,muted));
 HorizontalScrollView scrollTabs=new HorizontalScrollView(this);LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(0);tabs.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);for(String s:new String[]{"اليوم","مباشر","الأهلي","الدوريات","الإعدادات"}){TextView t=label(s,15,s.equals(tab)?green:white);tabs.addView(t);t.setOnClickListener(v->{tab=s;offset=0;show();});}scrollTabs.addView(tabs);add(root,scrollTabs);
 ScrollView sc=new ScrollView(this);body=column();body.setPadding(12,8,12,24);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 if(tab.equals("الإعدادات")){settings();return;}if(key.isEmpty()){add(body,label("لإظهار نتائج حقيقية، أضف مفتاح API-Football من الإعدادات.",17,white));return;}
 if(tab.equals("اليوم")){LinearLayout days=new LinearLayout(this);days.setOrientation(0);days.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);for(int d:new int[]{-1,0,1}){TextView t=label(d==-1?"أمس":d==0?"اليوم":"غدًا",16,green);days.addView(t);t.setOnClickListener(v->{offset=d;load();});}add(body,days);}load();}
 void settings(){add(body,label("مصدر النتائج: API-Football",21,white));add(body,label("المفتاح من dashboard.api-football.com. تغطية المباريات حسب خطة مزود البيانات.",15,muted));EditText e=new EditText(this);e.setText(key);e.setSingleLine(true);e.setHint("API Key");e.setTextColor(white);add(body,e);action(body,"حفظ المفتاح",()->{key=e.getText().toString().trim();getPreferences(0).edit().putString("key",key).apply();tab="اليوم";show();});}
 String date(){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("Asia/Riyadh"));c.add(Calendar.DATE,offset);SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setTimeZone(TimeZone.getTimeZone("Asia/Riyadh"));return f.format(c.getTime());}
 void load(){body.removeAllViews();add(body,label("جاري تحميل المباريات…",16,muted));String date=date();new Thread(()->{try{URL u=new URL("https://v3.football.api-sports.io/fixtures?date="+date+"&timezone=Asia%2FRiyadh");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestProperty("x-apisports-key",key);c.setConnectTimeout(12000);c.setReadTimeout(15000);InputStream in=c.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] a=new byte[4096];int n;while((n=in.read(a))!=-1)b.write(a,0,n);JSONObject j=new JSONObject(b.toString("UTF-8"));JSONArray games=j.getJSONArray("response");runOnUiThread(()->render(games));}catch(Exception ex){runOnUiThread(()->{body.removeAllViews();add(body,label("تعذر جلب النتائج. تحقق من الإنترنت ومفتاح API.",16,white));});}}).start();}
 void render(JSONArray games){body.removeAllViews();add(body,label(tab.equals("الأهلي")?"💚 الأهلي السعودي":tab.equals("مباشر")?"🔴 مباشر":tab.equals("الدوريات")?"🏆 الدوريات":"📅 مباريات "+date(),22,white));action(body,"↻ تحديث",this::load);int count=0;
 for(int i=0;i<games.length();i++){JSONObject g=games.optJSONObject(i);if(g==null)continue;JSONObject league=g.optJSONObject("league"),teams=g.optJSONObject("teams"),fixture=g.optJSONObject("fixture"),goals=g.optJSONObject("goals");if(league==null||teams==null||fixture==null)continue;int id=league.optInt("id");boolean allowed=false;for(int k:ids)if(k==id)allowed=true;if(!allowed)continue;JSONObject h=teams.optJSONObject("home"),a=teams.optJSONObject("away");if(h==null||a==null)continue;String hn=h.optString("name"),an=a.optString("name");String names=(hn+" "+an).toLowerCase(Locale.ROOT);boolean ahli=(names.contains("al ahli")||names.contains("al-ahli")||names.contains("الأهلي"))&&id==307;if(tab.equals("الأهلي")&&!ahli)continue;
 JSONObject status=fixture.optJSONObject("status");String st=status==null?"":status.optString("short");boolean live=Arrays.asList("1H","2H","HT","ET","P","BT","INT").contains(st);if(tab.equals("مباشر")&&!live)continue;
 String score=goals==null||goals.isNull("home")?"—":goals.optString("home");score+=" : "+(goals==null||goals.isNull("away")?"—":goals.optString("away"));String dt=fixture.optString("date");String time=dt.length()>15?dt.substring(11,16):"";String detail=live?"🔴 مباشر":st.equals("FT")?"انتهت":time+" السعودية";
 LinearLayout box=column();GradientDrawable shape=new GradientDrawable();shape.setColor(ahli?0xff124536:card);shape.setCornerRadius(24);box.setBackground(shape);box.setPadding(10,8,10,8);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=12;body.addView(box,p);add(box,label(league.optString("name"),13,green));add(box,label(hn+" × "+an,18,white));add(box,label(score,24,white));add(box,label(detail,13,muted));count++;}
 if(count==0)add(body,label("لا توجد مباريات متاحة ضمن البطولات المختارة.",16,muted));}
}